var player=UnityEngine.Object.FindFirstObjectByType<Poolcore.FirstPersonController>();var menu=UnityEngine.Object.FindFirstObjectByType<Poolcore.ExperienceMenu>();if(menu)menu.BeginAutomatedTest();var report=new System.Text.StringBuilder();int failures=0;
try{player.Teleport(new UnityEngine.Vector3(40.5f,.05f,42));player.transform.rotation=UnityEngine.Quaternion.identity;var route=new[]{new UnityEngine.Vector2(40.5f,60),new UnityEngine.Vector2(34.5f,61),new UnityEngine.Vector2(34.5f,90),new UnityEngine.Vector2(65.5f,90),new UnityEngine.Vector2(65.5f,61),new UnityEngine.Vector2(50,61),new UnityEngine.Vector2(50,70),new UnityEngine.Vector2(50,61),new UnityEngine.Vector2(40.5f,61),new UnityEngine.Vector2(40.5f,42),new UnityEngine.Vector2(41.8f,37),new UnityEngine.Vector2(42.3f,32),new UnityEngine.Vector2(41.8f,37),new UnityEngine.Vector2(40.5f,42)};
foreach(var target in route){int steps=0;var delta=target-new UnityEngine.Vector2(player.transform.position.x,player.transform.position.z);while(delta.magnitude>.12f&&steps++<2400){player.SimulateMovement(delta.normalized,false,1f/60);delta=target-new UnityEngine.Vector2(player.transform.position.x,player.transform.position.z);}bool pass=delta.magnitude<=.12f;if(!pass)failures++;report.AppendLine((pass?"PASS":"FAIL")+" "+target+" at "+player.transform.position);}}
finally{player.ResetToSpawn();}
report.AppendLine("Failures: "+failures);System.IO.File.WriteAllText("artifacts/contrast-wing/route.txt",report.ToString());return report.ToString();
